"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["flagged"] is True)
    return hits / len(events) if events else 0.0


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    hits = sum(1 for events in groups.values() for e in events if e["flagged"] is True)
    return hits / total if total else 0.0


def flags_in_window(daily_counts, days):
    """Sum the last days entries of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days else 0


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flag_values = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc
        if flag not in flag_values:
            raise ValueError(f"line {line_number}: flagged must be 1, 0 or empty")
        out.append({"id": id_, "day": day, "flagged": flag_values[flag]})
    return out


def dedupe_transcripts(events):
    """Keep the last record per id, sorted by day and id. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["flagged"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts

