"""Regression checks for each section of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1
@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False, None], 0.0),
     ([True, None], 0.5), ([True, False, None], 1 / 3), ([True], 1.0)],
)
def test_monitor_flag_rate_includes_none_in_denominator(flags, expected):
    result = monitor_flag_rate([event(str(i), i, flag) for i, flag in enumerate(flags)])
    assert result == expected
    assert isinstance(result, float)


# Section 2
@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_empty(groups):
    assert pooled_flag_rate(groups) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    shared = event("same", 1, True)
    groups = {
        "small": [shared],
        "large": [shared, event("b", 2, False), event("c", 3, None)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


# Section 3
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4
def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", " \t# another,comment",
             " a , -2 , 1 \n", " b , +3 , 0 ", " c , 4 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        event("a", -2, True), event("b", 3, False), event("c", 4, None)
    ]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", "  # comment", " \t"]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "ok,1,1", " \t", bad_line])


# Section 5
def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [event("b", 0, True), event("a", 9, True), event("c", 2, True),
              event("b", 2, False), event("a", 2, None), event("c", 1, False)]
    original = events[:]
    assert dedupe_transcripts(events) == [events[5], events[4], events[3]]
    assert events == original
    assert dedupe_transcripts([]) == []


# Section 6
def test_daily_flag_counts_fills_days_and_ignores_outside_range():
    events = [event("before", -1, True), event("a", 0, True), event("b", 0, True),
              event("c", 1, False), event("d", 2, None), event("e", 3, True),
              event("after", 5, True)]
    assert daily_flag_counts(events, 0, 4) == [2, 0, 0, 1, 0]
    assert daily_flag_counts(events, 0, 0) == [2]
    assert daily_flag_counts(events, 4, 3) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


# Section 7
@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_monitor_summary_pooled_rounded_rate_and_calendar_window(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 4, True),
                  event("d", 5, None), event("e", 5, False), event("f", 5, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8
@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                                         (10, ["best", "a", "z", "zero"])])
def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [event("z", 1, True), event("z2", 2, None)],
        "empty": [],
        "zero": [event("zero", 1, False)],
        "a": [event("a", 1, True), event("a2", 2, False)],
        "best": [event("best", 1, True)],
    }
    assert top_flagged_groups(groups, n) == expected
    assert top_flagged_groups({}, n) == []
    assert top_flagged_groups({"empty": []}, n) == []


# Section 9
def test_flag_rate_by_group_sorted_keys_and_empty_group():
    groups = {"z": [], "b": [event("b", 1, False)],
              "a": [event("a", 1, True), event("a2", 2, None)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


# Section 10
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, 2, 0, 3], 2), ([1, -1, 2], 1), ([1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
